const savePath = './src/modules/javascript/rules';
const rows = [...md.matchAll(/^\|\s*\[([^\]]+)\]\((https?:\/\/[^)]+)\)\s*\|\s*([^\n|]+?)(?=\s*\|)/gm)]
    .map(([, name, link, desc]) => ({ name, link, desc: desc.trim() }));
function createTypeScriptRules(rules) {
    rules.forEach((rule) => {
        const className = rule.name.split('-').map((name) => name[0].toUpperCase() + name.slice(1)).join('');
        let template = `
import {RuleInterface} from "../../../models/rule.model";
import {Message} from "../../../models/message.model";
import {MessageType} from "../../../enum/message.enum";
import {Result as AuditResult} from "lighthouse/types/lhr/audit-result";
import {CheerioAPI} from "cheerio";
import {Result} from "html-validate";
import {LightHouseAuditType} from "../../../types/modules.type";
import {EslintHelper} from "../../../linters/eslint.helper";
import {ESLint, Linter} from "eslint";


export class ${className}Rule implements RuleInterface {
     id: string = '${rule.name}';
    tags: string[] = ['javascript'];
    dom: CheerioAPI;
    lightHouse: LightHouseAuditType;
    ruleFlow!: MessageType;
    htmlValidator: Result[];
    eslint: ESLint.LintResult[];
    description: string = \`${rule.desc}\`;
    ruleUrl: string = '${rule.link}';

    constructor(dom: CheerioAPI, lightHouse: LightHouseAuditType, htmlValidator: Result[], eslint: ESLint.LintResult[]) {
        this.dom = dom;
        this.eslint = eslint;
        this.lightHouse = lightHouse;
        this.htmlValidator = htmlValidator;
    }

    check(): Message[] {
        return EslintHelper.identifyRule(this.id, this.ruleFlow,  this.eslint);
    }
}`
        fs.writeFileSync(savePath+ `/${rule.name}.rule.ts`, template)
    });

}

createTypeScriptRules(rows);